FMT_CONSTEXPR void intersect_text_style_colors(
    bool& fg_set, uint32_t& fg_value, bool& fg_rgb, bool& bg_set,
    uint32_t& bg_value, bool& bg_rgb, uint8_t& ems, bool rhs_fg_set,
    uint32_t rhs_fg_value, bool rhs_fg_rgb, bool rhs_bg_set,
    uint32_t rhs_bg_value, bool rhs_bg_rgb, uint8_t rhs_ems) {
  color_fg_set_ = fg_set;
  color_bg_set_ = bg_set;
  color_emphasis_ = ems;
  if (!fg_set) {
    fg_set = rhs_fg_set;
    fg_value = rhs_fg_value;
    fg_rgb = rhs_fg_rgb;
    color_fg_value_ = rhs_fg_value;
    color_is_rgb_ = rhs_fg_rgb;
  } else if (rhs_fg_set) {
    if (!fg_rgb || !rhs_fg_rgb)
      FMT_THROW(format_error("can't AND a terminal color"));
    fg_value &= rhs_fg_value;
    color_fg_value_ = fg_value;
    color_is_rgb_ = true;
  }
  if (!bg_set) {
    bg_set = rhs_bg_set;
    bg_value = rhs_bg_value;
    bg_rgb = rhs_bg_rgb;
    color_bg_value_ = rhs_bg_value;
  } else if (rhs_bg_set) {
    if (!bg_rgb || !rhs_bg_rgb)
      FMT_THROW(format_error("can't AND a terminal color"));
    bg_value &= rhs_bg_value;
    color_bg_value_ = bg_value;
  }
  ems = static_cast<uint8_t>(ems & rhs_ems);
  color_emphasis_ = ems;
  color_fg_set_ = fg_set;
  color_bg_set_ = bg_set;
  color_esc_len_ = (fg_set ? 1 : 0) + (bg_set ? 1 : 0) + (ems != 0 ? 1 : 0);
}

FMT_CONSTEXPR void build_terminal_color_sequence(Char* buffer,
                                                 uint32_t value,
                                                 bool is_background) {
  color_is_rgb_ = false;
  color_esc_len_ = 0;
  if (is_background) {
    color_bg_set_ = true;
    color_bg_value_ = value;
    value += 10u;
  } else {
    color_fg_set_ = true;
    color_fg_value_ = value;
  }
  size_t index = 0;
  buffer[index++] = static_cast<Char>('\x1b');
  buffer[index++] = static_cast<Char>('[');
  if (value >= 100u) {
    buffer[index++] = static_cast<Char>('1');
    value %= 100u;
  }
  buffer[index++] = static_cast<Char>('0' + value / 10u);
  buffer[index++] = static_cast<Char>('0' + value % 10u);
  buffer[index++] = static_cast<Char>('m');
  buffer[index++] = static_cast<Char>('\0');
  color_esc_len_ = static_cast<int>(index);
}

FMT_CONSTEXPR void encode_rgb_component(uint8_t component, Char* out,
                                        char delimiter) {
  color_is_rgb_ = true;
  color_esc_len_ += 4;
  out[0] = static_cast<Char>('0' + component / 100);
  out[1] = static_cast<Char>('0' + component / 10 % 10);
  out[2] = static_cast<Char>('0' + component % 10);
  out[3] = static_cast<Char>(delimiter);
  if (delimiter == 'm')
    color_fg_value_ = (color_fg_value_ & 0xffff00u) | component;
  else if (color_esc_len_ <= 12)
    color_fg_value_ = (color_fg_value_ & 0x00ffffu) |
                      (static_cast<uint32_t>(component) << 16);
  else
    color_fg_value_ = (color_fg_value_ & 0xff00ffu) |
                      (static_cast<uint32_t>(component) << 8);
}

FMT_CONSTEXPR void build_rgb_color_sequence(Char* buffer, uint32_t rgb_color,
                                            const char* esc) {
  color_is_rgb_ = true;
  color_fg_set_ = true;
  color_fg_value_ = rgb_color;
  color_esc_len_ = 0;
  for (int i = 0; i < 7; i++) {
    buffer[i] = static_cast<Char>(esc[i]);
    ++color_esc_len_;
  }
  encode_rgb_component(static_cast<uint8_t>((rgb_color >> 16) & 0xff),
                       buffer + 7, ';');
  encode_rgb_component(static_cast<uint8_t>((rgb_color >> 8) & 0xff),
                       buffer + 11, ';');
  encode_rgb_component(static_cast<uint8_t>(rgb_color & 0xff), buffer + 15,
                       'm');
  buffer[19] = static_cast<Char>(0);
  color_esc_len_ = 20;
}

FMT_CONSTEXPR void resolve_emphasis_codes(uint8_t em, uint8_t* em_codes) {
  color_emphasis_ = em;
  color_esc_len_ = 0;
  em_codes[0] = (em & 1) != 0 ? 1 : 0;
  em_codes[1] = (em & 2) != 0 ? 2 : 0;
  em_codes[2] = (em & 4) != 0 ? 3 : 0;
  em_codes[3] = (em & 8) != 0 ? 4 : 0;
  em_codes[4] = (em & 16) != 0 ? 5 : 0;
  em_codes[5] = (em & 32) != 0 ? 7 : 0;
  em_codes[6] = (em & 64) != 0 ? 8 : 0;
  em_codes[7] = (em & 128) != 0 ? 9 : 0;
  for (int i = 0; i < 8; ++i) {
    if (em_codes[i] != 0) color_esc_len_ += 4;
  }
}

FMT_CONSTEXPR void build_emphasis_sequence(Char* buffer, uint8_t em) {
  uint8_t em_codes[8] = {};
  resolve_emphasis_codes(em, em_codes);
  size_t index = 0;
  for (size_t i = 0; i < 8; ++i) {
    if (!em_codes[i]) continue;
    buffer[index++] = static_cast<Char>('\x1b');
    buffer[index++] = static_cast<Char>('[');
    buffer[index++] = static_cast<Char>('0' + em_codes[i]);
    buffer[index++] = static_cast<Char>('m');
  }
  buffer[index++] = static_cast<Char>(0);
  color_emphasis_ = em;
  color_esc_len_ = static_cast<int>(index);
}

FMT_CONSTEXPR void build_ansi_color_escape(Char* buffer, bool is_rgb,
                                           uint32_t value, const char* esc) {
  color_is_rgb_ = is_rgb;
  color_fg_value_ = value;
  if (!is_rgb) {
    bool is_background = esc[2] == '4';
    color_bg_set_ = is_background;
    color_fg_set_ = !is_background;
    build_terminal_color_sequence(buffer, value, is_background);
    return;
